// Practical Debounce implementation
function debounce(fn, delay) {
  let timerId;
  return function (...args) {
    clearTimeout(timerId); // Reset timer on each trigger
    timerId = setTimeout(() => {
      fn.apply(this, args);
    }, delay);
  };
}

