	jobs := make(chan int, numJobs)
	results := make(chan int, numJobs)

	// Launch 3 concurrent workers in pool
	for w := 1; w <= 3; w++ {
		go worker(w, jobs, results)
	}

	for j := 1; j <= numJobs; j++ {
		jobs <- j
	}
	close(jobs)

